WITH cleaned AS (SELECT *, DATEDIFF(CURRENT_DATE(), paid_at) AS days_since_paid_at FROM payments WHERE method IS DISTINCT FROM 'bank_transfer' AND paid_at >= DATE '2023-05-15'), flagged AS (SELECT *, CASE WHEN LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) IS NULL OR paid_at > LAG(paid_at) OVER (PARTITION BY order_id ORDER BY paid_at, id) + INTERVAL 7 DAYS THEN 1 ELSE 0 END AS is_new_burst FROM cleaned), sessionized AS (SELECT *, SUM(is_new_burst) OVER (PARTITION BY order_id ORDER BY paid_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS session_no FROM flagged) SELECT DATE_TRUNC('WEEK', paid_at) AS week_start, DATE_TRUNC('QUARTER', paid_at) AS quarter_start, SIZE(COLLECT_SET(method)) AS num_methods, MIN(paid_at) AS started_at, PERCENT_RANK() OVER (PARTITION BY DATE_TRUNC('WEEK', paid_at) ORDER BY SIZE(COLLECT_SET(method)) DESC) AS num_methods_percent_rank FROM sessionized GROUP BY DATE_TRUNC('WEEK', paid_at), DATE_TRUNC('QUARTER', paid_at) ORDER BY quarter_start DESC;
